import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BfWdyVj4.js";const u=JSON.parse('{"title":"The Android apps","description":"","frontmatter":{},"headers":[],"relativePath":"developers/android.md","filePath":"developers/android.md","lastUpdated":1793095158000}'),o={name:"developers/android.md"};function d(r,e,n,h,l,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="the-android-apps" tabindex="-1">The Android apps <a class="header-anchor" href="#the-android-apps" aria-label="Permalink to &quot;The Android apps&quot;">​</a></h1><h2 id="the-display-app-instead-of-fully-kiosk" tabindex="-1">The display app (instead of Fully Kiosk) <a class="header-anchor" href="#the-display-app-instead-of-fully-kiosk" aria-label="Permalink to &quot;The display app (instead of Fully Kiosk)&quot;">​</a></h2><p><code>android/</code> is a tiny app (<code>party.froghub</code>, minSdk 22, so it runs on Fire OS 5): a full-screen WebView that</p><ul><li>keeps the screen on and plays sound without a tap;</li><li>gives the microphone to Frog Hub&#39;s own site only, and stays on that site;</li><li>retries every 10 seconds when the server can&#39;t be reached;</li><li>never closes on Back.</li></ul><p><strong>Five quick taps in the top-left corner</strong> open its settings (address, open on startup, exit). It asks for Frog Hub&#39;s address on first start, or set it over adb:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> party.froghub/.MainActivity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://froghub.example</span></span></code></pre></div><p>Debug it with <code>chrome://inspect</code> over adb.</p><h3 id="old-fire-tablets-and-let-s-encrypt" tabindex="-1">Old Fire tablets and Let&#39;s Encrypt <a class="header-anchor" href="#old-fire-tablets-and-let-s-encrypt" aria-label="Permalink to &quot;Old Fire tablets and Let&#39;s Encrypt&quot;">​</a></h3><p>Fire OS 5 doesn&#39;t trust Let&#39;s Encrypt&#39;s root certificates (ISRG Root X1 and X2), so its WebView refuses sites that use them and shows a black page. The app bundles both roots (<code>res/raw/</code>) and, when the only error is &quot;untrusted&quot;, checks the site again itself (<code>IsrgTrust.java</code>: the full chain against those roots, the hostname, and the same certificate) before going ahead.</p><p>Its WebView is Chrome 59, which has no ES modules, so <code>vite.config.js</code> also builds a legacy version for Chrome 59.</p><h3 id="building-it" tabindex="-1">Building it <a class="header-anchor" href="#building-it" aria-label="Permalink to &quot;Building it&quot;">​</a></h3><p>Ready-built copies of both apps are on the <a href="https://github.com/froghub-assistant/froghub/releases/latest" target="_blank" rel="noreferrer">latest release</a>, built by <code>.github/workflows/android.yml</code> whenever <code>android/</code> or <code>android-admin/</code> changes, and signed with Frog Hub&#39;s release key so each one installs over the last.</p><p>To build it yourself, use <code>android/build.sh</code> on an x86 computer with the Android SDK (its build tools don&#39;t run on ARM). It signs with that computer&#39;s debug key (or <code>KEYSTORE</code> and <code>KS_PASS</code>), so updates built there install over the old one, but not over a release copy: Android only updates an app signed with the same key, so uninstall first to switch.</p><h2 id="the-admin-app" tabindex="-1">The admin app <a class="header-anchor" href="#the-admin-app" aria-label="Permalink to &quot;The admin app&quot;">​</a></h2><p><code>android-admin/</code> wraps <a href="/guide/grown-ups#the-admin-page">the admin page</a> as a phone app (<code>party.froghub.admin</code>, minSdk 22 = Android 5.1), with the same Let&#39;s Encrypt check. It asks for the site on first start. <a href="https://github.com/froghub-assistant/froghub/releases/latest/download/froghub-admin.apk" target="_blank" rel="noreferrer">Download it</a>, or build it like the display app, with <code>android-admin/build.sh</code>.</p>',15)])])}const b=a(o,[["render",d]]);export{u as __pageData,b as default};
